
SELECT
  u.id AS user_id,
  CASE (((CAST(RIGHT(u.username, 2) AS UNSIGNED) - 1) % 6) + 1)
    WHEN 1 THEN '/image/defaultPfp.png'
    ELSE CONCAT('/image/defaultPfp', (((CAST(RIGHT(u.username, 2) AS UNSIGNED) - 1) % 6) + 1), '.png')
  END AS avatar,
  CONCAT('Test User ', RIGHT(u.username, 2)) AS display_name,
  CONCAT('Automatikus teszt profil: ', u.username) AS description,
  'public' AS visibility
FROM users u
WHERE u.username REGEXP '^testuser[0-9]{2}$'
  AND CAST(RIGHT(u.username, 2) AS UNSIGNED) BETWEEN 1 AND 50
ON DUPLICATE KEY UPDATE
  avatar = VALUES(avatar),
  display_name = VALUES(display_name),
  description = VALUES(description),
  visibility = VALUES(visibility);
  
